// Riwayat Pembelian, Pemakaian Material, dan Pemakaian Peralatan khusus untuk SATU proyek (Rekap Proyek)
// -- projectPurchases/projectUsage/projectPeralatanUsage sudah difilter ke gudangId proyek itu (proj:<id>).
function riwayatMaterialPeralatanHtml(project, projectPurchases, projectUsage, projectPeralatanUsage, materials) {
  const findMaterial = (id) => materials.find((m) => m.id === id);
  const sortedPurchases = [...projectPurchases].sort((a, b) => (a.date < b.date ? 1 : -1));
  const sortedUsage = [...projectUsage].sort((a, b) => (a.date < b.date ? 1 : -1));
  const sortedPeralatan = [...projectPeralatanUsage].sort((a, b) => (a.date < b.date ? 1 : -1));
  const totalPembelian = sortedPurchases.reduce((s, p) => s + purchaseTotal(p), 0);

  const belanjaRows = sortedPurchases.map((p, i) => {
    const items = purchaseItems(p);
    return items.map((it, j) => `
      <tr><td>${j === 0 ? i + 1 : ''}</td><td>${j === 0 ? escapeHtml(p.date) : ''}</td><td>${j === 0 ? escapeHtml(p.noNota || '') : ''}</td>
      <td>${j === 0 ? escapeHtml(p.supplierName || '') : ''}</td><td>${escapeHtml(it.materialName)}</td>
      <td>${it.qty} ${escapeHtml(it.unit || '')}</td><td>${formatRupiah(it.price)}</td><td>${formatRupiah((Number(it.qty) || 0) * (Number(it.price) || 0))}</td></tr>`).join('');
  }).join('');

  const usageRows = sortedUsage.map((u, i) => `
    <tr><td>${i + 1}</td><td>${escapeHtml(u.date)}</td><td>${escapeHtml(u.materialName || findMaterial(u.materialId)?.name || '-')}</td>
    <td>${u.qty} ${escapeHtml(u.unit || '')}</td><td>${escapeHtml(u.note || '')}</td></tr>`).join('');

  const peralatanRows = sortedPeralatan.map((u, i) => `
    <tr><td>${i + 1}</td><td>${escapeHtml(u.date)}</td><td>${escapeHtml(u.peralatanNama || '-')}</td>
    <td>${escapeHtml(u.workerName || '-')}</td><td>${escapeHtml(u.note || '')}</td></tr>`).join('');

  return `<h2>RIWAYAT MATERIAL / PERALATAN — ${escapeHtml(project?.name || '-')}</h2>
    <h3>Riwayat Pembelian Material (${sortedPurchases.length} nota)</h3>
    ${sortedPurchases.length ? `<table><thead><tr><th>No</th><th>Tanggal</th><th>No. Nota</th><th>Suplier</th><th>Material</th><th>Qty</th><th>Harga</th><th>Subtotal</th></tr></thead>
    <tbody>${belanjaRows}</tbody>
    <tfoot><tr class="bold"><td colspan="7">TOTAL PEMBELIAN</td><td>${formatRupiah(totalPembelian)}</td></tr></tfoot></table>` : '<p>Belum ada pembelian material untuk proyek ini.</p>'}
    <h3>Riwayat Pemakaian Material (${sortedUsage.length} catatan)</h3>
    ${sortedUsage.length ? `<table><thead><tr><th>No</th><th>Tanggal</th><th>Material</th><th>Qty</th><th>Catatan</th></tr></thead>
    <tbody>${usageRows}</tbody></table>` : '<p>Belum ada catatan pemakaian material untuk proyek ini.</p>'}
    <h3>Riwayat Pemakaian Peralatan (${sortedPeralatan.length} catatan)</h3>
    ${sortedPeralatan.length ? `<table><thead><tr><th>No</th><th>Tanggal</th><th>Peralatan</th><th>Dipakai Oleh</th><th>Catatan</th></tr></thead>
    <tbody>${peralatanRows}</tbody></table>` : '<p>Belum ada catatan pemakaian peralatan untuk proyek ini.</p>'}`;
}

function exportRiwayatMaterialPeralatanPDF(project, projectPurchases, projectUsage, projectPeralatanUsage, materials) {
  try {
    const doc = new window.jspdf.jsPDF({ orientation: 'portrait', unit: 'pt', format: 'a4' });
    let y = pdfAddHeader(doc, 'Riwayat Material / Peralatan', project?.name || '-');

    const findMaterial = (id) => materials.find((m) => m.id === id);
    const sortedPurchases = [...projectPurchases].sort((a, b) => (a.date < b.date ? 1 : -1));
    const sortedUsage = [...projectUsage].sort((a, b) => (a.date < b.date ? 1 : -1));
    const sortedPeralatan = [...projectPeralatanUsage].sort((a, b) => (a.date < b.date ? 1 : -1));

    const section = (title, head, rows, footRow) => {
      if (y > 680) { doc.addPage(); y = 40; }
      doc.setFont('helvetica', 'bold'); doc.setFontSize(11); doc.setTextColor(...PDF_NAVY);
      doc.text(title, 40, y); y += 6;
      if (!rows.length) {
        doc.setFont('helvetica', 'italic'); doc.setFontSize(8.5); doc.setTextColor(...PDF_SLATE);
        doc.text('Belum ada data.', 40, y + 10);
        y += 26;
        return;
      }
      doc.autoTable({
        startY: y, margin: { left: 40, right: 40 }, head: [head], body: rows,
        foot: footRow ? [footRow] : undefined,
        styles: { fontSize: 8, textColor: PDF_INK },
        headStyles: { fillColor: PDF_NAVY, textColor: [242, 236, 217] },
        footStyles: { fillColor: [241, 236, 221], textColor: PDF_NAVY, fontStyle: 'bold' },
        alternateRowStyles: { fillColor: [250, 248, 241] },
      });
      y = doc.lastAutoTable.finalY + 22;
    };

    const belanjaBody = [];
    let totalPembelian = 0;
    sortedPurchases.forEach((p) => {
      purchaseItems(p).forEach((it, j) => {
        const subtotal = (Number(it.qty) || 0) * (Number(it.price) || 0);
        totalPembelian += subtotal;
        belanjaBody.push([j === 0 ? p.date : '', j === 0 ? (p.noNota || '-') : '', j === 0 ? (p.supplierName || '-') : '', it.materialName, `${it.qty} ${it.unit || ''}`, formatRupiah(it.price), formatRupiah(subtotal)]);
      });
    });
    section('Riwayat Pembelian Material', ['Tanggal', 'No. Nota', 'Suplier', 'Material', 'Qty', 'Harga', 'Subtotal'], belanjaBody,
      ['TOTAL PEMBELIAN', '', '', '', '', '', formatRupiah(totalPembelian)]);

    section('Riwayat Pemakaian Material', ['Tanggal', 'Material', 'Qty', 'Catatan'],
      sortedUsage.map((u) => [u.date, u.materialName || findMaterial(u.materialId)?.name || '-', `${u.qty} ${u.unit || ''}`, u.note || '']));

    section('Riwayat Pemakaian Peralatan', ['Tanggal', 'Peralatan', 'Dipakai Oleh', 'Catatan'],
      sortedPeralatan.map((u) => [u.date, u.peralatanNama || '-', u.workerName || '-', u.note || '']));

    pdfFinishAllPages(doc);
    doc.save(`riwayat-material-peralatan-${(project?.name || 'proyek').replace(/\s+/g, '-').toLowerCase()}.pdf`);
  } catch (err) {
    console.error('Gagal ekspor PDF Riwayat Material/Peralatan:', err);
    alert('Gagal membuat file PDF. Coba lagi.');
  }
}

function exportBelanjaPDF(sorted, total) {
  try {
    const doc = new window.jspdf.jsPDF({ orientation: 'portrait', unit: 'pt', format: 'a4' });
    let y = pdfAddHeader(doc, 'Belanja Harian Material', `${sorted.length} nota`);

    const body = [];
    sorted.forEach((p, i) => {
      const items = purchaseItems(p);
      items.forEach((it, j) => {
        body.push([
          j === 0 ? String(i + 1) : '', j === 0 ? p.date : '', j === 0 ? (p.noNota || '-') : '', j === 0 ? (p.supplierName || '-') : '',
          it.materialName, `${it.qty} ${it.unit || ''}`, formatRupiah(it.price), formatRupiah((Number(it.qty) || 0) * (Number(it.price) || 0)),
        ]);
      });
    });
    doc.autoTable({
      startY: y, margin: { left: 40, right: 40 },
      head: [['No', 'Tanggal', 'No. Nota', 'Suplier', 'Material', 'Qty', 'Harga', 'Subtotal']],
      body,
      foot: [['', '', '', '', '', '', 'TOTAL', formatRupiah(total)]],
      styles: { fontSize: 7.5, textColor: PDF_INK },
      headStyles: { fillColor: PDF_NAVY, textColor: [242, 236, 217] },
      footStyles: { fillColor: [241, 236, 221], textColor: PDF_NAVY, fontStyle: 'bold' },
      alternateRowStyles: { fillColor: [250, 248, 241] },
    });

    pdfFinishAllPages(doc);
    doc.save('belanja-harian.pdf');
  } catch (err) {
    console.error('Gagal ekspor PDF Belanja:', err);
    alert('Gagal membuat file PDF. Coba lagi, atau gunakan tombol Cetak.');
  }
}

function exportRekapUpahPDF(rows, grand, filterLabel) {
  try {
    const doc = new window.jspdf.jsPDF({ orientation: 'portrait', unit: 'pt', format: 'a4' });
    let y = pdfAddHeader(doc, 'Rekap Upah Tukang', filterLabel);

    const body = rows.map((r) => {
      const bayarKasbonTotal = r.workerKasbonPayments.reduce((s, p) => s + (Number(p.amount) || 0), 0);
      return [
        r.worker.name, r.worker.position || '-', `${r.totalHari} hr / ${r.totalJamLembur} j`,
        formatRupiah(r.totalUpah), formatRupiah(bayarKasbonTotal), formatRupiah(r.diterima), formatRupiah(r.totalKasbon), formatRupiah(r.sisa),
      ];
    });
    const grandBayarKasbon = rows.reduce((s, r) => s + r.workerKasbonPayments.reduce((s2, p) => s2 + (Number(p.amount) || 0), 0), 0);
    doc.autoTable({
      startY: y, margin: { left: 40, right: 40 },
      head: [['Nama', 'Jabatan', 'Hari/Lembur', 'Total Upah', 'Bayar Kasbon', 'Upah yang Diterima', 'Sisa Kasbon', 'Sisa Upah']],
      body,
      foot: [['', '', 'TOTAL', formatRupiah(grand.totalUpah), formatRupiah(grandBayarKasbon), formatRupiah(grand.diterima), formatRupiah(grand.totalKasbon), formatRupiah(grand.sisa)]],
      styles: { fontSize: 7.5, textColor: PDF_INK },
      headStyles: { fillColor: PDF_NAVY, textColor: [242, 236, 217] },
      footStyles: { fillColor: [241, 236, 221], textColor: PDF_NAVY, fontStyle: 'bold' },
      alternateRowStyles: { fillColor: [250, 248, 241] },
    });

    pdfFinishAllPages(doc);
    doc.save('rekap-upah.pdf');
  } catch (err) {
    console.error('Gagal ekspor PDF Rekap Upah:', err);
    alert('Gagal membuat file PDF. Coba lagi, atau gunakan tombol Cetak.');
  }
}

function exportSlipGajiPDF(row, filterLabel) {
  try {
    const { worker, totalUpah, totalHari, totalJamLembur, diterima, totalKasbon, sisa, workerPayments, workerKasbon, workerKasbonPayments, weekBreakdown, evidenceFilled, evidenceExpected } = row;
    const doc = new window.jspdf.jsPDF({ orientation: 'portrait', unit: 'pt', format: 'a4' });
    let y = pdfAddHeader(doc, 'Slip Gaji', filterLabel);

    doc.setFont('helvetica', 'bold'); doc.setFontSize(12); doc.setTextColor(...PDF_NAVY);
    doc.text(worker.name, 40, y);
    doc.setFont('helvetica', 'normal'); doc.setFontSize(9); doc.setTextColor(...PDF_SLATE);
    doc.text(worker.position || '-', 40, y + 14);
    y += 34;

    // Ringkasan
    const bayarKasbonTotal = workerKasbonPayments.reduce((s, p) => s + (Number(p.amount) || 0), 0);
    const summary = [
      ['Hari Kerja', `${totalHari} hari`], ['Jam Lembur', `${totalJamLembur} jam`],
      ['Total Upah', formatRupiah(totalUpah)], ['Bayar Kasbon', formatRupiah(bayarKasbonTotal)],
      ['Diterima (cash)', formatRupiah(diterima)],
      ['Sisa Kasbon', formatRupiah(totalKasbon)], ['Sisa Upah Belum Dibayar', formatRupiah(sisa)],
    ];
    if (evidenceExpected > 0) summary.push(['Bukti Foto Kehadiran', `${evidenceFilled}/${evidenceExpected} periode`]);
    doc.autoTable({
      startY: y, margin: { left: 40, right: 40 }, theme: 'plain',
      body: summary.map(([a, b]) => [a, b]),
      styles: { fontSize: 9.5, textColor: PDF_INK, cellPadding: { top: 4, bottom: 4, left: 0, right: 0 } },
      columnStyles: { 0: { textColor: PDF_SLATE, cellWidth: 150 }, 1: { fontStyle: 'bold', textColor: PDF_NAVY } },
    });
    y = doc.lastAutoTable.finalY + 20;

    const section = (title, head, rows2) => {
      if (!rows2.length) return;
      if (y > 700) { doc.addPage(); y = 40; }
      doc.setFont('helvetica', 'bold'); doc.setFontSize(10.5); doc.setTextColor(...PDF_NAVY);
      doc.text(title, 40, y); y += 6;
      doc.autoTable({
        startY: y, margin: { left: 40, right: 40 }, head: [head], body: rows2,
        styles: { fontSize: 8, textColor: PDF_INK },
        headStyles: { fillColor: [241, 236, 221], textColor: PDF_NAVY },
        alternateRowStyles: { fillColor: [250, 248, 241] },
      });
      y = doc.lastAutoTable.finalY + 20;
    };

    section('Rincian per Periode', ['Periode', 'Proyek', 'Hari', 'Lembur (j)', 'Upah'],
      weekBreakdown.map((wk) => [wk.weekLabel, wk.projectName, String(wk.totalHariBayar), String(wk.totalJamLembur), formatRupiah(wk.totalUpah)]));

    const dailyRows = [];
    weekBreakdown.forEach((wk) => {
      (wk.dailyDetail || []).forEach((d) => {
        let ket = d.hariHadirHariItu === 1 ? 'Hadir' : d.hariHadirHariItu === 0.5 ? 'Hadir 1/2 hari' : '-';
        if (d.hariTambahanHariItu > 0) ket += ` — lembur ${d.jamLembur}j = +${d.hariTambahanHariItu} hari`;
        else if (d.jamSisaHariItu > 0) ket += ` — lembur ${d.jamSisaHariItu} jam`;
        dailyRows.push([d.label, ket]);
      });
    });
    section('Rincian Harian', ['Tanggal', 'Keterangan'], dailyRows);

    section('Riwayat Pembayaran Upah', ['Tanggal', 'Jumlah'],
      workerPayments.map((p) => [p.date, formatRupiah(p.amount)]));

    section('Riwayat Kasbon Diberikan', ['Tanggal', 'Jumlah', 'Catatan'],
      workerKasbon.map((k) => [k.date, formatRupiah(k.amount), k.note || '']));

    section('Riwayat Pelunasan Kasbon', ['Tanggal', 'Jumlah'],
      workerKasbonPayments.map((p) => [p.date, formatRupiah(p.amount)]));

    pdfFinishAllPages(doc);
    doc.save(`slip-gaji-${worker.name.replace(/\s+/g, '-').toLowerCase()}.pdf`);
  } catch (err) {
    console.error('Gagal ekspor PDF Slip Gaji:', err);
    alert('Gagal membuat file PDF. Coba lagi, atau gunakan tombol Cetak.');
  }
}

/* ---------------- AHSP (Analisa Harga Satuan Pekerjaan) ---------------- */

function ahspBaseHarga(komponen) {
  return (komponen || []).reduce((s, k) => s + (Number(k.koefisien) || 0) * (Number(k.hargaSatuan) || 0), 0);
}
function ahspFinalHarga(komponen, overheadProfitPercent) {
  const base = ahspBaseHarga(komponen);
  return base * (1 + (Number(overheadProfitPercent) || 0) / 100);
}
function emptyAhspKomponen() {
  return { id: uid(), jenis: 'bahan', nama: '', satuan: '', koefisien: '', hargaSatuan: '' };
}
const AHSP_JENIS_LABEL = { bahan: 'Bahan', upah: 'Upah', alat: 'Alat' };
const AHSP_SUMBER_LIST = ['AHSP Cipta Karya', 'AHSP Bina Marga', 'AHSP SDA', 'AHSP SNI', 'Custom'];

// Kelompokkan item AHSP berdasarkan pola kode standar resmi (Permen PUPR), supaya
// daftar tidak terlalu panjang saat menyusun RAB. Kategori diturunkan dari kode,
// tidak disimpan sebagai data terpisah -- jadi tidak perlu impor ulang.
function kategoriAhsp(item) {
  const kode = (item.kode || '').trim();
  if (item.sumber === 'AHSP Bina Marga') {
    const m = kode.match(/^(\d+)\./);
    const divisi = m ? Number(m[1]) : 0;
    const MAP_BM = {
      1: 'UMUM (Persiapan & Mobilisasi)', 2: 'DRAINASE', 3: 'PEKERJAAN TANAH',
      4: 'PELEBARAN PERKERASAN & BAHU JALAN', 5: 'PERKERASAN BERBUTIR & JALAN COR',
      6: 'JALAN ASPAL', 7: 'STRUKTUR & JEMBATAN', 8: 'PENGEMBALIAN KONDISI & MINOR',
      9: 'PEKERJAAN HARIAN & LAIN-LAIN', 10: 'PEMELIHARAAN RUTIN',
    };
    return MAP_BM[divisi] || 'LAINNYA';
  }
  if (item.sumber === 'AHSP Cipta Karya') {
    if (/^A\.1\./.test(kode)) return 'PERSIAPAN';
    if (/^A\.2\./.test(kode)) return 'TANAH';
    if (/^A\.3\./.test(kode)) return 'PONDASI';
    if (/^A\.4\.1\./.test(kode)) return 'BETON';
    if (/^A\.4\.2\./.test(kode)) return 'BESI DAN ALUMUNIUM';
    if (/^A\.4\.3\./.test(kode)) return 'KAYU';
    if (/^A\.4\.4\./.test(kode)) return 'PASANGAN';
    if (/^A\.4\.5\./.test(kode)) return 'PENUTUP LANTAI DAN DINDING';
    if (/^A\.4\.6\./.test(kode)) return 'PLAFOND';
    if (/^A\.4\.7\./.test(kode)) return 'FINISHING (PENGECATAN)';
    if (/^A\.5\./.test(kode)) return 'SANITASI / MEP';
    if (/^CK-INT\./.test(kode)) return 'INTERIOR';
    if (/^(Ls|Taksir|CK-ASH|spl)\./.test(kode) || kode === 'spl') return 'LAINNYA (TAKSIR/LUMPSUM)';
    return 'LAINNYA';
  }
  return item.sumber || 'LAINNYA';
}
